class Solution {
  private static final long MOD = 1_000_000_007L;

  public int maxNiceDivisors(int primeFactors) {
    if (primeFactors <= 3) return primeFactors;
    long q = primeFactors / 3, r = primeFactors % 3;
    if (r == 0) return (int) pow(3, q);
    if (r == 1) return (int) (pow(3, q - 1) * 4 % MOD);
    return (int) (pow(3, q) * 2 % MOD);
  }

  private long pow(long a, long e) {
    long r = 1;
    while (e > 0) {
      if ((e & 1) == 1) r = r * a % MOD;
      a = a * a % MOD;
      e >>= 1;
    }
    return r;
  }
}
